module filter_fifo(
  input         clock,
                reset,
  input  [43:0] io_data_i,
  input         io_read_en,
                io_write_en,
  input  [43:0] io_wconflict_data,
  input         io_wconflict_en,
  output        io_conflict,
  output [43:0] io_data_o,
  output        io_empty,
                io_full
