  reg  [43:0]      fifo_buffer_0;
  reg  [43:0]      fifo_buffer_1;
  reg  [43:0]      fifo_buffer_2;
  reg  [43:0]      fifo_buffer_3;
  reg  [43:0]      fifo_buffer_4;
  reg  [43:0]      fifo_buffer_5;
  reg  [43:0]      fifo_buffer_6;
  reg  [43:0]      fifo_buffer_7;
  reg  [3:0]       read_ptr;
  reg  [3:0]       write_ptr;
  reg  [7:0]       exist_flag;
  wire             full_temp =
    read_ptr[3] != write_ptr[3] & read_ptr[2:0] == write_ptr[2:0];
  wire             empty_temp = read_ptr == write_ptr;
  wire             wcnt_flag = ~full_temp & io_write_en;
  wire [7:0][43:0] _GEN =
    {{fifo_buffer_7},
     {fifo_buffer_6},
     {fifo_buffer_5},
     {fifo_buffer_4},
     {fifo_buffer_3},
     {fifo_buffer_2},
     {fifo_buffer_1},
     {fifo_buffer_0}};
  always @(posedge clock) begin
    if (wcnt_flag & write_ptr[2:0] == 3'h0)
      fifo_buffer_0 <= io_data_i;
    if (wcnt_flag & write_ptr[2:0] == 3'h1)
      fifo_buffer_1 <= io_data_i;
    if (wcnt_flag & write_ptr[2:0] == 3'h2)
      fifo_buffer_2 <= io_data_i;
    if (wcnt_flag & write_ptr[2:0] == 3'h3)
      fifo_buffer_3 <= io_data_i;
    if (wcnt_flag & write_ptr[2:0] == 3'h4)
      fifo_buffer_4 <= io_data_i;
    if (wcnt_flag & write_ptr[2:0] == 3'h5)
      fifo_buffer_5 <= io_data_i;
    if (wcnt_flag & write_ptr[2:0] == 3'h6)
      fifo_buffer_6 <= io_data_i;
    if (wcnt_flag & (&(write_ptr[2:0])))
      fifo_buffer_7 <= io_data_i;
  end // always @(posedge)
  wire [7:0]       _GEN_0 = {5'h0, write_ptr[2:0]};
  wire             rcnt_flag = ~empty_temp & io_read_en;
  wire [7:0]       _GEN_1 = {5'h0, read_ptr[2:0]};
  always @(posedge clock or posedge reset) begin
    if (reset) begin
      read_ptr <= 4'h0;
      write_ptr <= 4'h0;
      exist_flag <= 8'h0;
    end
    else begin
      if (rcnt_flag)
        read_ptr <= read_ptr + 4'h1;
      if (wcnt_flag)
        write_ptr <= write_ptr + 4'h1;
      if (wcnt_flag & rcnt_flag)
        exist_flag <= exist_flag & ~(8'h1 << _GEN_1) | 8'h1 << _GEN_0;
      else if (rcnt_flag)
        exist_flag <= exist_flag & ~(8'h1 << _GEN_1);
      else
        exist_flag <= {8{wcnt_flag}} & 8'h1 << _GEN_0 | exist_flag;
    end
  end // always @(posedge, posedge)
  `ifdef ENABLE_INITIAL_REG_
    `ifdef FIRRTL_BEFORE_INITIAL
      `FIRRTL_BEFORE_INITIAL
    `endif // FIRRTL_BEFORE_INITIAL
    initial begin
      if (reset) begin
        read_ptr = 4'h0;
        write_ptr = 4'h0;
        exist_flag = 8'h0;
      end
    end // initial
    `ifdef FIRRTL_AFTER_INITIAL
      `FIRRTL_AFTER_INITIAL
    `endif // FIRRTL_AFTER_INITIAL
  `endif // ENABLE_INITIAL_REG_
  assign io_conflict =
    io_wconflict_en
    & (exist_flag[0] & fifo_buffer_0[43:8] == io_wconflict_data[43:8] | exist_flag[1]
       & fifo_buffer_1[43:8] == io_wconflict_data[43:8] | exist_flag[2]
       & fifo_buffer_2[43:8] == io_wconflict_data[43:8] | exist_flag[3]
       & fifo_buffer_3[43:8] == io_wconflict_data[43:8] | exist_flag[4]
       & fifo_buffer_4[43:8] == io_wconflict_data[43:8] | exist_flag[5]
       & fifo_buffer_5[43:8] == io_wconflict_data[43:8] | exist_flag[6]
       & fifo_buffer_6[43:8] == io_wconflict_data[43:8] | exist_flag[7]
