  wire         _CmdQueue_io_deq_bits_CmdType;
  wire [1:0]   requestVec = {io_WrCmdFromAddrMap_valid, io_RdCmdFromAddrMap_valid};
  wire         ChosenRead =
    requestVec == 2'h1 | (&requestVec)
    & ((io_RdCmdFromAddrMap_bits_token[6] ^ io_WrCmdFromAddrMap_bits_token[6])
       & io_RdCmdFromAddrMap_bits_token[5:0] > io_WrCmdFromAddrMap_bits_token[5:0]
       | (io_RdCmdFromAddrMap_bits_token[6] ^ ~(io_WrCmdFromAddrMap_bits_token[6]))
       & io_RdCmdFromAddrMap_bits_token[5:0] < io_WrCmdFromAddrMap_bits_token[5:0]);
