  wire         _io_RequestwData_bits_T = io_RequestwData_ready & _DataQueue_io_deq_valid;
  Queue64_1_Anon CmdQueue (
    .clock               (clock),
    .reset               (reset),
    .io_enq_ready        (_CmdQueue_io_enq_ready),
    .io_enq_valid
      (ChosenRead ? io_RdCmdFromAddrMap_valid : io_WrCmdFromAddrMap_valid),
    .io_enq_bits_rank
      (ChosenRead ? io_RdCmdFromAddrMap_bits_rank : io_WrCmdFromAddrMap_bits_rank),
    .io_enq_bits_bg
      (ChosenRead ? io_RdCmdFromAddrMap_bits_bg : io_WrCmdFromAddrMap_bits_bg),
    .io_enq_bits_bank
      (ChosenRead ? io_RdCmdFromAddrMap_bits_bank : io_WrCmdFromAddrMap_bits_bank),
    .io_enq_bits_row
      (ChosenRead ? io_RdCmdFromAddrMap_bits_row : io_WrCmdFromAddrMap_bits_row),
    .io_enq_bits_col
      (ChosenRead ? io_RdCmdFromAddrMap_bits_col : io_WrCmdFromAddrMap_bits_col),
    .io_enq_bits_pri
      (ChosenRead ? io_RdCmdFromAddrMap_bits_pri : io_WrCmdFromAddrMap_bits_pri),
    .io_enq_bits_token
      (ChosenRead ? io_RdCmdFromAddrMap_bits_token : io_WrCmdFromAddrMap_bits_token),
    .io_enq_bits_CmdType (ChosenRead),
    .io_deq_ready        (io_RequestCmd_ready),
