    .io_deq_bits_rank    (_CmdQueue_io_deq_bits_rank),
    .io_deq_bits_bg      (_CmdQueue_io_deq_bits_bg),
    .io_deq_bits_bank    (_CmdQueue_io_deq_bits_bank),
    .io_deq_bits_row     (_CmdQueue_io_deq_bits_row),
    .io_deq_bits_col     (_CmdQueue_io_deq_bits_col),
