    .clock             (clock),
    .reset             (reset),
    .io_enq_valid
      (~ChosenRead & io_WrCmdFromAddrMap_ready_0 & io_WrCmdFromAddrMap_valid),
    .io_enq_bits_wdata (ChosenRead ? 512'h0 : io_WrDataFromAddrMap_bits_wdata),
    .io_enq_bits_wstrb (ChosenRead ? 64'h0 : io_WrDataFromAddrMap_bits_wstrb),
    .io_deq_ready      (io_RequestwData_ready),
    .io_deq_valid      (_DataQueue_io_deq_valid),
