           : blockTagReadRespHold_r_TagWays_2_tag)
      : tagWays_2_tag;
  assign io_out_bits_tags_TagWays_2_valid =
    isBlockReq
      ? (_blockTagReadRespHold_T_1
           ? io_tagReadResp_TagWays_2_valid
           : blockTagReadRespHold_r_TagWays_2_valid)
      : tagWays_2_valid;
  assign io_out_bits_tags_TagWays_2_dirty =
    isBlockReq
      ? (_blockTagReadRespHold_T_1
           ? io_tagReadResp_TagWays_2_dirty
           : blockTagReadRespHold_r_TagWays_2_dirty)
      : tagWays_2_dirty;
  assign io_out_bits_tags_TagWays_3_tag =
    isBlockReq
      ? (_blockTagReadRespHold_T_1
           ? io_tagReadResp_TagWays_3_tag
           : blockTagReadRespHold_r_TagWays_3_tag)
      : tagWays_3_tag;
  assign io_out_bits_tags_TagWays_3_valid =
    isBlockReq
      ? (_blockTagReadRespHold_T_1
           ? io_tagReadResp_TagWays_3_valid
           : blockTagReadRespHold_r_TagWays_3_valid)
      : tagWays_3_valid;
  assign io_out_bits_tags_TagWays_3_dirty =
    isBlockReq
      ? (_blockTagReadRespHold_T_1
           ? io_tagReadResp_TagWays_3_dirty
           : blockTagReadRespHold_r_TagWays_3_dirty)
      : tagWays_3_dirty;
  assign io_out_bits_datas_dataWays_0 =
    isBlockReq
      ? (_blockDataReadRespHold_T_1
           ? io_dataReadResp_dataWays_0
           : blockDataReadRespHold_r_dataWays_0)
      : io_inFire ? io_dataReadResp_dataWays_0 : dataReadRespHold_r_dataWays_0;
  assign io_out_bits_datas_dataWays_1 =
    isBlockReq
      ? (_blockDataReadRespHold_T_1
           ? io_dataReadResp_dataWays_1
           : blockDataReadRespHold_r_dataWays_1)
      : io_inFire ? io_dataReadResp_dataWays_1 : dataReadRespHold_r_dataWays_1;
  assign io_out_bits_datas_dataWays_2 =
    isBlockReq
      ? (_blockDataReadRespHold_T_1
           ? io_dataReadResp_dataWays_2
           : blockDataReadRespHold_r_dataWays_2)
      : io_inFire ? io_dataReadResp_dataWays_2 : dataReadRespHold_r_dataWays_2;
  assign io_out_bits_datas_dataWays_3 =
    isBlockReq
      ? (_blockDataReadRespHold_T_1
           ? io_dataReadResp_dataWays_3
           : blockDataReadRespHold_r_dataWays_3)
      : io_inFire ? io_dataReadResp_dataWays_3 : dataReadRespHold_r_dataWays_3;
  assign io_out_bits_hit = io_out_bits_hit_0;
  assign io_out_bits_waymask =
    io_out_bits_hit_0
      ? hitVec
      : (|{~tagWays_3_valid, ~tagWays_2_valid, ~tagWays_1_valid, ~tagWays_0_valid})
          ? (tagWays_3_valid
               ? {1'h0,
                  (|{~tagWays_3_valid, ~tagWays_2_valid})
                    ? 3'h4
                    : {1'h0,
                       (|{~tagWays_3_valid, ~tagWays_2_valid, ~tagWays_1_valid})
                         ? 2'h2
                         : 2'h1}}
               : 4'h8)
          : (|{~tagWays_3_dirty, ~tagWays_2_dirty, ~tagWays_1_dirty, ~tagWays_0_dirty})
              ? (tagWays_3_dirty
                   ? {1'h0,
                      (|{~tagWays_3_dirty, ~tagWays_2_dirty})
                        ? 3'h4
                        : {1'h0,
                           (|{~tagWays_3_dirty, ~tagWays_2_dirty, ~tagWays_1_dirty})
                             ? 2'h2
                             : 2'h1}}
                   : 4'h8)
              : (&readyVec)
                  ? 4'h1 << victimWaymask_lfsr[1:0]
                  : readyVec == 4'h0
                      ? (_firstReadyWaymask_T_1 ? firstReadyVec : firstReadyWaymask_r)
                      : tagWays_3_ready
                          ? 4'h8
                          : {1'h0,
                             (|{tagWays_3_ready, tagWays_2_ready})
                               ? 3'h4
                               : {1'h0,
                                  (|{tagWays_3_ready, tagWays_2_ready, tagWays_1_ready})
                                    ? 2'h2
                                    : 2'h1}};
  assign io_out_bits_isForwardData = isForwardData | isForwardDataReg;
  assign io_out_bits_forwardData_waymask =
    isForwardData ? io_dataWriteBus_req_bits_waymask : forwardDataReg_waymask;
  assign io_out_bits_forwardData_wdata =
    isForwardData ? io_dataWriteBus_req_bits_wdata : forwardDataReg_wdata;
  assign io_out_bits_wDataBundle_wdata = io_RequestwData_bits_wdata;
  assign io_out_bits_wDataBundle_wstrb = io_RequestwData_bits_wstrb;
  assign io_out_bits_conflictWCB = io_conflictWCB | conflictWCBReg;
  assign io_out_bits_conflictWCBData =
    io_conflictWCB ? io_conflictWCBData : io_out_bits_conflictWCBData_r;
  assign io_RequestwData_ready = _io_RequestwData_ready_T & ~io_in_bits_req_CmdType;
  assign io_searchReq_valid = io_inFire;
  assign io_searchReq_bits_rank = io_in_bits_req_rank;
  assign io_searchReq_bits_bg = io_in_bits_req_bg;
  assign io_searchReq_bits_bank = io_in_bits_req_bank;
  assign io_searchReq_bits_row = io_in_bits_req_row;
  assign io_searchReq_bits_col = io_in_bits_req_col;
  assign io_searchReq_bits_pri = io_in_bits_req_pri;
  assign io_searchReq_bits_token = io_in_bits_req_token;
  assign io_searchReq_bits_CmdType = io_in_bits_req_CmdType;
  assign io_blockedReq_valid = block;
  assign io_blockedReq_bits_rank = io_in_bits_req_rank;
  assign io_blockedReq_bits_bg = io_in_bits_req_bg;
  assign io_blockedReq_bits_bank = io_in_bits_req_bank;
  assign io_blockedReq_bits_row = io_in_bits_req_row;
  assign io_blockedReq_bits_col = io_in_bits_req_col;
endmodule

module CacheStage3(
  input          clock,
                 reset,
  output         io_in_ready,
  input          io_in_valid,
                 io_in_bits_req_rank,
  input  [1:0]   io_in_bits_req_bg,
                 io_in_bits_req_bank,
  input  [15:0]  io_in_bits_req_row,
  input  [9:0]   io_in_bits_req_col,
  input          io_in_bits_req_pri,
