  input          io_in_bits_tags_TagWays_3_valid,
                 io_in_bits_tags_TagWays_3_dirty,
  input  [511:0] io_in_bits_datas_dataWays_0,
                 io_in_bits_datas_dataWays_1,
                 io_in_bits_datas_dataWays_2,
                 io_in_bits_datas_dataWays_3,
  input          io_in_bits_hit,
  input  [3:0]   io_in_bits_waymask,
  input          io_in_bits_isForwardData,
  input  [3:0]   io_in_bits_forwardData_waymask,
  input  [511:0] io_in_bits_forwardData_wdata,
                 io_in_bits_wDataBundle_wdata,
  input  [63:0]  io_in_bits_wDataBundle_wstrb,
  input          io_in_bits_conflictWCB,
  input  [511:0] io_in_bits_conflictWCBData,
  input          io_mshrReq_ready,
  output         io_mshrReq_valid,
                 io_mshrReq_bits_splitCmd_rank,
  output [1:0]   io_mshrReq_bits_splitCmd_bg,
                 io_mshrReq_bits_splitCmd_bank,
  output [15:0]  io_mshrReq_bits_splitCmd_row,
  output [9:0]   io_mshrReq_bits_splitCmd_col,
  output         io_mshrReq_bits_splitCmd_pri,
  output [6:0]   io_mshrReq_bits_splitCmd_token,
  output [3:0]   io_mshrReq_bits_waymask,
  input          io_wcbReq_ready,
  output         io_wcbReq_valid,
  output [511:0] io_wcbReq_bits_data,
  output [19:0]  io_wcbReq_bits_tag,
  output [6:0]   io_wcbReq_bits_set,
  output [2:0]   io_wcbReq_bits_bank,
  input          io_clearConflict_ready,
  output         io_clearConflict_valid,
  output [511:0] io_clearConflict_bits_wdata,
  output [63:0]  io_clearConflict_bits_wstrb,
  output         io_clearConflict_bits_overWrite,
  input          io_hitReadData_ready,
  output         io_hitReadData_valid,
  output [511:0] io_hitReadData_bits_rdata,
  output [6:0]   io_hitReadData_bits_rtoken,
  input          io_dataWriteBus_req_ready,
  output         io_dataWriteBus_req_valid,
  output [2:0]   io_dataWriteBus_req_bits_bank,
  output [6:0]   io_dataWriteBus_req_bits_set,
  output [3:0]   io_dataWriteBus_req_bits_waymask,
  output [511:0] io_dataWriteBus_req_bits_wdata,
  input          io_tagWriteBus_req_ready,
  output         io_tagWriteBus_req_valid,
  output [2:0]   io_tagWriteBus_req_bits_bank,
  output [6:0]   io_tagWriteBus_req_bits_set,
  output [3:0]   io_tagWriteBus_req_bits_waymask,
  output [19:0]  io_tagWriteBus_req_bits_wdata_tag,
  output         io_tagWriteBus_req_bits_wdata_valid,
                 io_tagWriteBus_req_bits_wdata_dirty,
                 io_tagWriteBus_req_bits_wdata_ready,
                 io_isFinish
);

  wire         tagArrayWriteValid;
  wire         dataArrayWriteValid;
  wire         io_wcbReq_valid_0;
  wire         io_hitReadData_valid_0;
  wire         io_mshrReq_valid_0;
  wire [2:0]   addr_bank = {io_in_bits_req_bank[0], io_in_bits_req_bg};
  wire [6:0]   addr_set = {io_in_bits_req_col[8:3], io_in_bits_req_bank[1]};
  wire [19:0]  addr_tag =
    {2'h0, io_in_bits_req_rank, io_in_bits_req_row, io_in_bits_req_col[9]};
  wire         hit = io_in_valid & io_in_bits_hit;
  wire [511:0] readData =
    io_in_bits_isForwardData & io_in_bits_waymask == io_in_bits_forwardData_waymask
      ? io_in_bits_forwardData_wdata
      : (io_in_bits_waymask[0] ? io_in_bits_datas_dataWays_0 : 512'h0)
        | (io_in_bits_waymask[1] ? io_in_bits_datas_dataWays_1 : 512'h0)
        | (io_in_bits_waymask[2] ? io_in_bits_datas_dataWays_2 : 512'h0)
        | (io_in_bits_waymask[3] ? io_in_bits_datas_dataWays_3 : 512'h0);
  reg          wcbReqFireReg;
  reg          clearConflictFireReg;
  reg          mshrReqFireReg;
  reg          arrayFireReg;
  reg          hitReadDataFireReg;
  wire         _wcbReqFireHold_T = io_wcbReq_ready & io_wcbReq_valid_0;
  wire         wcbReqFireHold = _wcbReqFireHold_T | wcbReqFireReg;
  wire         _mshrReqFireHold_T = io_mshrReq_ready & io_mshrReq_valid_0;
  wire         _arrayWriteBusFire_T_1 = io_tagWriteBus_req_ready & tagArrayWriteValid;
  wire         arrayFireHold = _arrayWriteBusFire_T_1 | arrayFireReg;
  wire         _hitReadIsFinish_T = io_hitReadData_ready & io_hitReadData_valid_0;
  wire         hitWrite = hit & ~io_in_bits_req_CmdType & io_in_valid;
  wire         hitRead = hit & io_in_bits_req_CmdType & io_in_valid;
  wire         missFullWrite = ~hit & ~io_in_bits_req_CmdType & io_in_valid;
  wire         _io_wcbReq_valid_T =
    (io_in_bits_waymask[0] & io_in_bits_tags_TagWays_0_valid | io_in_bits_waymask[1]
     & io_in_bits_tags_TagWays_1_valid | io_in_bits_waymask[2]
     & io_in_bits_tags_TagWays_2_valid | io_in_bits_waymask[3]
     & io_in_bits_tags_TagWays_3_valid)
    & (io_in_bits_waymask[0] & io_in_bits_tags_TagWays_0_dirty | io_in_bits_waymask[1]
       & io_in_bits_tags_TagWays_1_dirty | io_in_bits_waymask[2]
       & io_in_bits_tags_TagWays_2_dirty | io_in_bits_waymask[3]
       & io_in_bits_tags_TagWays_3_dirty);
  wire         missRead = ~hit & io_in_bits_req_CmdType & io_in_valid;
  assign io_mshrReq_valid_0 = missRead & ~io_in_bits_conflictWCB & ~mshrReqFireReg;
  wire         _dataArrayWrite_T = missRead & io_in_bits_conflictWCB;
  assign io_hitReadData_valid_0 = hitRead | _dataArrayWrite_T & ~hitReadDataFireReg;
  assign io_wcbReq_valid_0 =
    _io_wcbReq_valid_T & (missFullWrite | missRead) & ~wcbReqFireReg;
  wire         io_clearConflict_valid_0 =
    (missRead | missFullWrite) & io_in_bits_conflictWCB & ~clearConflictFireReg;
  wire         _tagArrayWriteValid_T = hitWrite | missFullWrite;
  assign dataArrayWriteValid =
    (_tagArrayWriteValid_T | _dataArrayWrite_T) & ~arrayFireReg;
  assign tagArrayWriteValid = (_tagArrayWriteValid_T | missRead) & ~arrayFireReg;
  wire [1:0]   _tagArrayWrite_T_11 = io_in_bits_conflictWCB ? 2'h1 : 2'h2;
  wire         io_isFinish_0 =
    hitRead & _hitReadIsFinish_T | hitWrite & io_dataWriteBus_req_ready
    & dataArrayWriteValid & _arrayWriteBusFire_T_1 | missFullWrite
    & (~_io_wcbReq_valid_T | wcbReqFireHold) & arrayFireHold | missRead
    & (io_in_bits_conflictWCB
         ? _hitReadIsFinish_T | hitReadDataFireReg
         : _mshrReqFireHold_T | mshrReqFireReg) & arrayFireHold
    & (~_io_wcbReq_valid_T | wcbReqFireHold);
  always @(posedge clock or posedge reset) begin
    if (reset) begin
      wcbReqFireReg <= 1'h0;
      clearConflictFireReg <= 1'h0;
      mshrReqFireReg <= 1'h0;
      arrayFireReg <= 1'h0;
      hitReadDataFireReg <= 1'h0;
    end
    else begin
      wcbReqFireReg <= ~io_isFinish_0 & (_wcbReqFireHold_T | wcbReqFireReg);
      clearConflictFireReg <=
        ~io_isFinish_0
        & (io_clearConflict_ready & io_clearConflict_valid_0 | clearConflictFireReg);
      mshrReqFireReg <= ~io_isFinish_0 & (_mshrReqFireHold_T | mshrReqFireReg);
      arrayFireReg <= ~io_isFinish_0 & (_arrayWriteBusFire_T_1 | arrayFireReg);
      hitReadDataFireReg <= ~io_isFinish_0 & (_hitReadIsFinish_T | hitReadDataFireReg);
    end
  end // always @(posedge, posedge)
  `ifdef ENABLE_INITIAL_REG_
    `ifdef FIRRTL_BEFORE_INITIAL
      `FIRRTL_BEFORE_INITIAL
    `endif // FIRRTL_BEFORE_INITIAL
    initial begin
      if (reset) begin
        wcbReqFireReg = 1'h0;
        clearConflictFireReg = 1'h0;
        mshrReqFireReg = 1'h0;
        arrayFireReg = 1'h0;
        hitReadDataFireReg = 1'h0;
      end
    end // initial
    `ifdef FIRRTL_AFTER_INITIAL
      `FIRRTL_AFTER_INITIAL
    `endif // FIRRTL_AFTER_INITIAL
  `endif // ENABLE_INITIAL_REG_
  assign io_in_ready = ~io_in_valid | io_isFinish_0;
  assign io_mshrReq_valid = io_mshrReq_valid_0;
  assign io_mshrReq_bits_splitCmd_rank = io_in_bits_req_rank;
  assign io_mshrReq_bits_splitCmd_bg = io_in_bits_req_bg;
  assign io_mshrReq_bits_splitCmd_bank = io_in_bits_req_bank;
  assign io_mshrReq_bits_splitCmd_row = io_in_bits_req_row;
  assign io_mshrReq_bits_splitCmd_col = io_in_bits_req_col;
  assign io_mshrReq_bits_splitCmd_pri = io_in_bits_req_pri;
  assign io_mshrReq_bits_splitCmd_token = io_in_bits_req_token;
  assign io_mshrReq_bits_waymask = io_in_bits_waymask;
  assign io_wcbReq_valid = io_wcbReq_valid_0;
  assign io_wcbReq_bits_data = readData;
  assign io_wcbReq_bits_tag =
    (io_in_bits_waymask[0] ? io_in_bits_tags_TagWays_0_tag : 20'h0)
    | (io_in_bits_waymask[1] ? io_in_bits_tags_TagWays_1_tag : 20'h0)
    | (io_in_bits_waymask[2] ? io_in_bits_tags_TagWays_2_tag : 20'h0)
    | (io_in_bits_waymask[3] ? io_in_bits_tags_TagWays_3_tag : 20'h0);
  assign io_wcbReq_bits_set = {io_in_bits_req_col[8:3], io_in_bits_req_bank[1]};
  assign io_wcbReq_bits_bank = {io_in_bits_req_bank[0], io_in_bits_req_bg};
  assign io_clearConflict_valid = io_clearConflict_valid_0;
  assign io_clearConflict_bits_wdata = io_in_bits_wDataBundle_wdata;
  assign io_clearConflict_bits_wstrb = io_in_bits_wDataBundle_wstrb;
  assign io_clearConflict_bits_overWrite = missFullWrite;
  assign io_hitReadData_valid = io_hitReadData_valid_0;
  assign io_hitReadData_bits_rdata = hitRead ? readData : io_in_bits_conflictWCBData;
  assign io_hitReadData_bits_rtoken = io_in_bits_req_token;
  assign io_dataWriteBus_req_valid = dataArrayWriteValid;
  assign io_dataWriteBus_req_bits_bank = addr_bank;
  assign io_dataWriteBus_req_bits_set = addr_set;
  assign io_dataWriteBus_req_bits_waymask = io_in_bits_waymask;
  assign io_dataWriteBus_req_bits_wdata =
    hitWrite | missFullWrite
      ? io_in_bits_wDataBundle_wdata
      : _dataArrayWrite_T ? io_in_bits_conflictWCBData : 512'h0;
  assign io_tagWriteBus_req_valid = tagArrayWriteValid;
  assign io_tagWriteBus_req_bits_bank = addr_bank;
  assign io_tagWriteBus_req_bits_set = addr_set;
  assign io_tagWriteBus_req_bits_waymask = io_in_bits_waymask;
  assign io_tagWriteBus_req_bits_wdata_tag =
    hitWrite | missFullWrite | missRead ? addr_tag : 20'h0;
  assign io_tagWriteBus_req_bits_wdata_valid = hitWrite | missFullWrite | missRead;
  assign io_tagWriteBus_req_bits_wdata_dirty =
    hitWrite
    | (missFullWrite ? ~io_in_bits_conflictWCB : missRead & _tagArrayWrite_T_11[1]);
  assign io_tagWriteBus_req_bits_wdata_ready =
    hitWrite | missFullWrite | missRead & _tagArrayWrite_T_11[0];
  assign io_isFinish = io_isFinish_0;
endmodule

