// VCS coverage exclude_file
module array_128x2048(
  input  [6:0]    RW0_addr,
  input           RW0_en,
                  RW0_clk,
                  RW0_wmode,
  input  [2047:0] RW0_wdata,
  output [2047:0] RW0_rdata,
  input  [3:0]    RW0_wmask
);

  reg [2047:0] Memory[0:127];
  reg [6:0]    _RW0_raddr_d0;
  reg          _RW0_ren_d0;
  reg          _RW0_rmode_d0;
  always @(posedge RW0_clk) begin
    _RW0_raddr_d0 <= RW0_addr;
    _RW0_ren_d0 <= RW0_en;
    _RW0_rmode_d0 <= RW0_wmode;
    if (RW0_en & RW0_wmask[0] & RW0_wmode)
      Memory[RW0_addr][32'h0 +: 512] <= RW0_wdata[511:0];
    if (RW0_en & RW0_wmask[1] & RW0_wmode)
      Memory[RW0_addr][32'h200 +: 512] <= RW0_wdata[1023:512];
    if (RW0_en & RW0_wmask[2] & RW0_wmode)
      Memory[RW0_addr][32'h400 +: 512] <= RW0_wdata[1535:1024];
    if (RW0_en & RW0_wmask[3] & RW0_wmode)
      Memory[RW0_addr][32'h600 +: 512] <= RW0_wdata[2047:1536];
  end // always @(posedge)
  assign RW0_rdata = _RW0_ren_d0 & ~_RW0_rmode_d0 ? Memory[_RW0_raddr_d0] : 2048'bx;
endmodule

module SRAMTemplate_by_10(
  input          clock,
  output         io_r_req_ready,
  input          io_r_req_valid,
  input  [6:0]   io_r_req_bits_setIdx,
  output [511:0] io_r_resp_data_0,
                 io_r_resp_data_1,
                 io_r_resp_data_2,
                 io_r_resp_data_3,
  input          io_w_req_valid,
  input  [6:0]   io_w_req_bits_setIdx,
  input  [511:0] io_w_req_bits_data_0,
                 io_w_req_bits_data_1,
                 io_w_req_bits_data_2,
                 io_w_req_bits_data_3,
  input  [3:0]   io_w_req_bits_waymask
);

  wire          realRen;
  wire [2047:0] _array_ext_RW0_rdata;
  assign realRen = io_r_req_valid & ~io_w_req_valid;
  array_128x2048 array_ext (
    .RW0_addr  (io_w_req_valid ? io_w_req_bits_setIdx : io_r_req_bits_setIdx),
    .RW0_en    (realRen | io_w_req_valid),
    .RW0_clk   (clock),
    .RW0_wmode (io_w_req_valid),
    .RW0_wdata
      ({io_w_req_bits_data_3,
        io_w_req_bits_data_2,
        io_w_req_bits_data_1,
        io_w_req_bits_data_0}),
    .RW0_rdata (_array_ext_RW0_rdata),
    .RW0_wmask (io_w_req_bits_waymask)
  );
  assign io_r_req_ready = ~io_w_req_valid;
  assign io_r_resp_data_0 = _array_ext_RW0_rdata[511:0];
  assign io_r_resp_data_1 = _array_ext_RW0_rdata[1023:512];
  assign io_r_resp_data_2 = _array_ext_RW0_rdata[1535:1024];
  assign io_r_resp_data_3 = _array_ext_RW0_rdata[2047:1536];
endmodule

