// VCS coverage exclude_file
module ram_2x50(
  input         R0_addr,
                R0_en,
                R0_clk,
  output [49:0] R0_data,
  input         W0_addr,
                W0_en,
                W0_clk,
  input  [49:0] W0_data
);

  reg [49:0] Memory[0:1];
  reg        _R0_en_d0;
  reg        _R0_addr_d0;
  always @(posedge R0_clk) begin
    _R0_en_d0 <= R0_en;
    _R0_addr_d0 <= R0_addr;
  end // always @(posedge)
  always @(posedge W0_clk) begin
    if (W0_en & 1'h1)
      Memory[W0_addr] <= W0_data;
  end // always @(posedge)
  assign R0_data = _R0_en_d0 ? Memory[_R0_addr_d0] : 50'bx;
endmodule

module Queue2_SchedulerSCGCmd(
  input         clock,
                reset,
  output        io_enq_ready,
  input         io_enq_valid,
                io_enq_bits_rank,
  input  [1:0]  io_enq_bits_bg,
                io_enq_bits_bank,
  input  [15:0] io_enq_bits_row,
  input  [9:0]  io_enq_bits_col,
  input         io_enq_bits_pri,
  input  [16:0] io_enq_bits_token,
  input         io_enq_bits_isRd,
                io_deq_ready,
  output        io_deq_valid,
                io_deq_bits_rank,
  output [1:0]  io_deq_bits_bg,
                io_deq_bits_bank,
  output [15:0] io_deq_bits_row,
  output [9:0]  io_deq_bits_col,
  output [16:0] io_deq_bits_token,
  output        io_deq_bits_isRd
);

  wire        io_enq_ready_0;
  wire [49:0] _ram_ext_R0_data;
  reg         wrap;
  reg         wrap_1;
  reg         maybe_full;
  wire        ptr_match = wrap == wrap_1;
  wire        empty = ptr_match & ~maybe_full;
  wire        do_enq = io_enq_ready_0 & io_enq_valid;
  wire        do_deq = io_deq_ready & ~empty;
  assign io_enq_ready_0 = io_deq_ready | ~(ptr_match & maybe_full);
  always @(posedge clock or posedge reset) begin
    if (reset) begin
      wrap <= 1'h0;
      wrap_1 <= 1'h0;
      maybe_full <= 1'h0;
    end
    else begin
      if (do_enq)
        wrap <= wrap - 1'h1;
      if (do_deq)
        wrap_1 <= wrap_1 - 1'h1;
      if (~(do_enq == do_deq))
        maybe_full <= do_enq;
    end
  end // always @(posedge, posedge)
  `ifdef ENABLE_INITIAL_REG_
    `ifdef FIRRTL_BEFORE_INITIAL
      `FIRRTL_BEFORE_INITIAL
    `endif // FIRRTL_BEFORE_INITIAL
    initial begin
      if (reset) begin
        wrap = 1'h0;
        wrap_1 = 1'h0;
        maybe_full = 1'h0;
      end
    end // initial
    `ifdef FIRRTL_AFTER_INITIAL
      `FIRRTL_AFTER_INITIAL
    `endif // FIRRTL_AFTER_INITIAL
  `endif // ENABLE_INITIAL_REG_
  ram_2x50 ram_ext (
    .R0_addr (do_deq ? ~wrap_1 & wrap_1 - 1'h1 : wrap_1),
    .R0_en   (1'h1),
    .R0_clk  (clock),
    .R0_data (_ram_ext_R0_data),
    .W0_addr (wrap),
    .W0_en   (do_enq),
    .W0_clk  (clock),
    .W0_data
      ({io_enq_bits_isRd,
        io_enq_bits_token,
        io_enq_bits_pri,
        io_enq_bits_col,
        io_enq_bits_row,
        io_enq_bits_bank,
        io_enq_bits_bg,
        io_enq_bits_rank})
  );
  assign io_enq_ready = io_enq_ready_0;
  assign io_deq_valid = ~empty;
  assign io_deq_bits_rank = _ram_ext_R0_data[0];
