module CmdArbiter(
  input         clock,
                reset,
  output        io_cmdIn_0_ready,
  input         io_cmdIn_0_valid,
                io_cmdIn_0_bits_rank,
  input  [1:0]  io_cmdIn_0_bits_bg,
                io_cmdIn_0_bits_bank,
  input  [15:0] io_cmdIn_0_bits_row,
  input  [9:0]  io_cmdIn_0_bits_col,
  input         io_cmdIn_0_bits_pri,
  input  [16:0] io_cmdIn_0_bits_token,
  output        io_cmdIn_1_ready,
  input         io_cmdIn_1_valid,
                io_cmdIn_1_bits_rank,
  input  [1:0]  io_cmdIn_1_bits_bg,
                io_cmdIn_1_bits_bank,
  input  [15:0] io_cmdIn_1_bits_row,
  input  [9:0]  io_cmdIn_1_bits_col,
