  input  [16:0] io_cmdIn_1_bits_token,
  output        io_cmdIn_2_ready,
  input         io_cmdIn_2_valid,
                io_cmdIn_2_bits_rank,
  input  [1:0]  io_cmdIn_2_bits_bg,
                io_cmdIn_2_bits_bank,
  input  [15:0] io_cmdIn_2_bits_row,
  input  [9:0]  io_cmdIn_2_bits_col,
  input         io_cmdIn_2_bits_pri,
  input  [16:0] io_cmdIn_2_bits_token,
  output        io_cmdIn_3_ready,
  input         io_cmdIn_3_valid,
                io_cmdIn_3_bits_rank,
  input  [1:0]  io_cmdIn_3_bits_bg,
                io_cmdIn_3_bits_bank,
  input  [15:0] io_cmdIn_3_bits_row,
  input  [9:0]  io_cmdIn_3_bits_col,
  input         io_cmdIn_3_bits_pri,
  input  [16:0] io_cmdIn_3_bits_token,
  input         io_cmdOut_ready,
  output        io_cmdOut_valid,
                io_cmdOut_bits_rank,
  output [1:0]  io_cmdOut_bits_bg,
                io_cmdOut_bits_bank,
  output [15:0] io_cmdOut_bits_row,
  output [9:0]  io_cmdOut_bits_col,
  output [16:0] io_cmdOut_bits_token,
  output        io_cmdOut_bits_isRd
);

  wire [1:0]       chosen;
  wire             _fifo_io_enq_ready;
  wire [3:0]       _GEN = '{1'h0, 1'h1, 1'h0, 1'h1};
  reg              fcPrefer;
  reg              frwPrefer;
  reg              crwPrefer;
  reg  [1:0]       fHoldPrefer;
  reg  [1:0]       cHoldPrefer;
  wire [3:0]       _GEN_0 =
    {{io_cmdIn_3_valid}, {io_cmdIn_2_valid}, {io_cmdIn_1_valid}, {io_cmdIn_0_valid}};
  wire [3:0]       _GEN_1 =
    {{io_cmdIn_3_bits_rank},
     {io_cmdIn_2_bits_rank},
     {io_cmdIn_1_bits_rank},
     {io_cmdIn_0_bits_rank}};
  wire [3:0][1:0]  _GEN_2 =
    {{io_cmdIn_3_bits_bg},
     {io_cmdIn_2_bits_bg},
     {io_cmdIn_1_bits_bg},
     {io_cmdIn_0_bits_bg}};
  wire [3:0][1:0]  _GEN_3 =
    {{io_cmdIn_3_bits_bank},
     {io_cmdIn_2_bits_bank},
     {io_cmdIn_1_bits_bank},
     {io_cmdIn_0_bits_bank}};
  wire [3:0][15:0] _GEN_4 =
    {{io_cmdIn_3_bits_row},
     {io_cmdIn_2_bits_row},
     {io_cmdIn_1_bits_row},
     {io_cmdIn_0_bits_row}};
  wire [3:0][9:0]  _GEN_5 =
    {{io_cmdIn_3_bits_col},
     {io_cmdIn_2_bits_col},
     {io_cmdIn_1_bits_col},
     {io_cmdIn_0_bits_col}};
  wire [3:0]       _GEN_6 =
    {{io_cmdIn_3_bits_pri},
     {io_cmdIn_2_bits_pri},
     {io_cmdIn_1_bits_pri},
     {io_cmdIn_0_bits_pri}};
  wire [3:0][16:0] _GEN_7 =
    {{io_cmdIn_3_bits_token},
     {io_cmdIn_2_bits_token},
     {io_cmdIn_1_bits_token},
     {io_cmdIn_0_bits_token}};
  wire             io_cmdIn_0_ready_0 = chosen == 2'h0 & _fifo_io_enq_ready;
  wire             io_cmdIn_1_ready_0 = chosen == 2'h1 & _fifo_io_enq_ready;
  wire             io_cmdIn_2_ready_0 = chosen == 2'h2 & _fifo_io_enq_ready;
  wire             io_cmdIn_3_ready_0 = (&chosen) & _fifo_io_enq_ready;
  wire [2:0]       _GEN_8 =
    {1'h0, {1'h0, io_cmdIn_0_valid} + {1'h0, io_cmdIn_1_valid}}
    + {1'h0, {1'h0, io_cmdIn_2_valid} + {1'h0, io_cmdIn_3_valid}};
  wire             _GEN_9 = fHoldPrefer != 2'h1;
  assign chosen =
    (|(_GEN_8[2:1]))
      ? (fcPrefer
           ? (io_cmdIn_0_valid | io_cmdIn_1_valid
                ? {1'h0, _GEN_9 & (fHoldPrefer == 2'h2 | ~(frwPrefer & io_cmdIn_0_valid))}
                : cHoldPrefer == 2'h1
                    ? 2'h2
                    : cHoldPrefer == 2'h2
                        ? 2'h3
                        : {1'h1, ~(crwPrefer & io_cmdIn_2_valid)})
           : io_cmdIn_2_valid | io_cmdIn_3_valid
               ? (cHoldPrefer == 2'h1
                    ? 2'h2
                    : cHoldPrefer == 2'h2
                        ? 2'h3
                        : {1'h1, ~(crwPrefer & io_cmdIn_2_valid)})
               : {1'h0, _GEN_9 & (fHoldPrefer == 2'h2 | ~(frwPrefer & io_cmdIn_0_valid))})
      : {|{io_cmdIn_3_valid, io_cmdIn_2_valid}, io_cmdIn_3_valid | io_cmdIn_1_valid};
  wire             _fHoldPrefer_T_8 = fHoldPrefer == 2'h0;
  wire             _cHoldPrefer_T_8 = cHoldPrefer == 2'h0;
  wire             _fHoldPrefer_T = io_cmdIn_0_ready_0 & io_cmdIn_0_valid;
  wire             _fHoldPrefer_T_2 = io_cmdIn_1_ready_0 & io_cmdIn_1_valid;
  wire             _cHoldPrefer_T = io_cmdIn_2_ready_0 & io_cmdIn_2_valid;
  wire             _cHoldPrefer_T_2 = io_cmdIn_3_ready_0 & io_cmdIn_3_valid;
  always @(posedge clock or posedge reset) begin
    if (reset) begin
      fcPrefer <= 1'h0;
      frwPrefer <= 1'h0;
      crwPrefer <= 1'h0;
      fHoldPrefer <= 2'h0;
      cHoldPrefer <= 2'h0;
    end
    else begin
      fcPrefer <=
        ~(_fHoldPrefer_T | _fHoldPrefer_T_2)
        & (_cHoldPrefer_T | _cHoldPrefer_T_2 | fcPrefer);
      frwPrefer <= ~_fHoldPrefer_T & (_fHoldPrefer_T_2 | frwPrefer);
      crwPrefer <= ~_cHoldPrefer_T & (_cHoldPrefer_T_2 | crwPrefer);
      if (_fHoldPrefer_T | _fHoldPrefer_T_2) begin
        if (_fHoldPrefer_T & io_cmdIn_1_valid)
          fHoldPrefer <= 2'h2;
        else
          fHoldPrefer <= {1'h0, _fHoldPrefer_T_2 & io_cmdIn_0_valid};
      end
      else if (_fHoldPrefer_T_8 & io_cmdIn_0_valid)
        fHoldPrefer <= 2'h1;
      else if (_fHoldPrefer_T_8 & io_cmdIn_1_valid)
        fHoldPrefer <= 2'h2;
      if (_cHoldPrefer_T | _cHoldPrefer_T_2) begin
        if (_cHoldPrefer_T & io_cmdIn_3_valid)
          cHoldPrefer <= 2'h2;
        else
          cHoldPrefer <= {1'h0, _cHoldPrefer_T_2 & io_cmdIn_2_valid};
      end
      else if (_cHoldPrefer_T_8 & io_cmdIn_2_valid)
        cHoldPrefer <= 2'h1;
      else if (_cHoldPrefer_T_8 & io_cmdIn_3_valid)
        cHoldPrefer <= 2'h2;
    end
  end // always @(posedge, posedge)
  `ifdef ENABLE_INITIAL_REG_
    `ifdef FIRRTL_BEFORE_INITIAL
      `FIRRTL_BEFORE_INITIAL
    `endif // FIRRTL_BEFORE_INITIAL
    initial begin
      if (reset) begin
        fcPrefer = 1'h0;
        frwPrefer = 1'h0;
        crwPrefer = 1'h0;
        fHoldPrefer = 2'h0;
        cHoldPrefer = 2'h0;
      end
    end // initial
    `ifdef FIRRTL_AFTER_INITIAL
      `FIRRTL_AFTER_INITIAL
    `endif // FIRRTL_AFTER_INITIAL
  `endif // ENABLE_INITIAL_REG_
  Queue2_SchedulerSCGCmd fifo (
    .clock             (clock),
    .reset             (reset),
    .io_enq_ready      (_fifo_io_enq_ready),
    .io_enq_valid      (_GEN_0[chosen]),
    .io_enq_bits_rank  (_GEN_1[chosen]),
    .io_enq_bits_bg    (_GEN_2[chosen]),
    .io_enq_bits_bank  (_GEN_3[chosen]),
    .io_enq_bits_row   (_GEN_4[chosen]),
    .io_enq_bits_col   (_GEN_5[chosen]),
    .io_enq_bits_pri   (_GEN_6[chosen]),
    .io_enq_bits_token (_GEN_7[chosen]),
    .io_enq_bits_isRd  (_GEN[chosen]),
    .io_deq_ready      (io_cmdOut_ready),
    .io_deq_valid      (io_cmdOut_valid),
    .io_deq_bits_rank  (io_cmdOut_bits_rank),
    .io_deq_bits_bg    (io_cmdOut_bits_bg),
    .io_deq_bits_bank  (io_cmdOut_bits_bank),
    .io_deq_bits_row   (io_cmdOut_bits_row),
    .io_deq_bits_col   (io_cmdOut_bits_col),
    .io_deq_bits_token (io_cmdOut_bits_token),
    .io_deq_bits_isRd  (io_cmdOut_bits_isRd)
  );
  assign io_cmdIn_0_ready = io_cmdIn_0_ready_0;
  assign io_cmdIn_1_ready = io_cmdIn_1_ready_0;
  assign io_cmdIn_2_ready = io_cmdIn_2_ready_0;
  assign io_cmdIn_3_ready = io_cmdIn_3_ready_0;
endmodule

