  input        io_cas_req,
  input  [4:0] io_cas_chosen,
  input        io_pre_req,
  input  [4:0] io_pre_chosen,
  output       io_act_won,
  output [4:0] io_act_chosen_won,
  output       io_cas_won,
  output [4:0] io_cas_chosen_won,
  output       io_pre_won,
  output [4:0] io_pre_chosen_won
);

  wire _GEN = io_act_req | io_cas_req;
  assign io_act_won = io_act_req;
  assign io_act_chosen_won = io_act_req ? io_act_chosen : 5'h0;
  assign io_cas_won = ~io_act_req & io_cas_req;
  assign io_cas_chosen_won = io_act_req | ~io_cas_req ? 5'h0 : io_cas_chosen;
  assign io_pre_won = ~_GEN & io_pre_req;
  assign io_pre_chosen_won = _GEN | ~io_pre_req ? 5'h0 : io_pre_chosen;
endmodule

