  reg          RdValid;
  reg          RdValidCntr;
  reg  [255:0] RdData_buf_0;
  reg  [255:0] RdData_buf_1;
  always @(posedge clock) begin
    wrdata_delay_io_vld_REG <= write_vld;
    wrdata_delay_io_write_phase0_REG <= io_dfi_write_ph_0;
    wrdata_delay_io_write_phase1_REG <= io_dfi_write_ph_1;
  end // always @(posedge)
  wire         _GEN = RdValidCntr & (|io_dfi_rddata_in_dfi_rddata_valid);
  always @(posedge clock or posedge reset) begin
    if (reset) begin
      RdValid <= 1'h0;
      RdValidCntr <= 1'h0;
      RdData_buf_0 <= 256'h0;
      RdData_buf_1 <= 256'h0;
    end
    else begin
      RdValid <= _GEN;
      if (|io_dfi_rddata_in_dfi_rddata_valid)
        RdValidCntr <= RdValidCntr - 1'h1;
      if (_GEN | ~(~RdValidCntr & (|io_dfi_rddata_in_dfi_rddata_valid))) begin
      end
      else
        RdData_buf_0 <= io_dfi_rddata_in_dfi_rddata;
      if (_GEN)
        RdData_buf_1 <= io_dfi_rddata_in_dfi_rddata;
    end
  end // always @(posedge, posedge)
  `ifdef ENABLE_INITIAL_REG_
    `ifdef FIRRTL_BEFORE_INITIAL
      `FIRRTL_BEFORE_INITIAL
    `endif // FIRRTL_BEFORE_INITIAL
    initial begin
      if (reset) begin
        RdValid = 1'h0;
        RdValidCntr = 1'h0;
        RdData_buf_0 = 256'h0;
        RdData_buf_1 = 256'h0;
      end
    end // initial
    `ifdef FIRRTL_AFTER_INITIAL
      `FIRRTL_AFTER_INITIAL
    `endif // FIRRTL_AFTER_INITIAL
  `endif // ENABLE_INITIAL_REG_
  WrData_offset wrdata_delay (
    .clock                 (clock),
    .reset                 (reset),
    .io_vld                (wrdata_delay_io_vld_REG),
    .io_write_phase0       (wrdata_delay_io_write_phase0_REG),
    .io_write_phase1       (wrdata_delay_io_write_phase1_REG),
    .io_write_latency      ({27'h0, io_tphy_wrlat + io_tphy_wrdata}),
    .io_write_data         (io_dfi_wrdata_wdata),
    .io_offset_data        (io_dfi_wrdata_ch_out_dfi_wdata),
    .io_dfi_parameter_mode (io_dfi_parameter_mode)
  );
  dfi_en_offset wrdata_en_delay (
    .clock                 (clock),
    .reset                 (reset),
    .io_vld                (write_vld),
    .io_vld_ph0            (io_dfi_write_ph_0),
    .io_vld_ph1            (io_dfi_write_ph_1),
    .io_latency            ({27'h0, io_tphy_wrlat}),
    .io_offset_out         (io_dfi_wrdata_ch_out_dfi_wrdata_en),
    .io_dfi_parameter_mode (io_dfi_parameter_mode)
  );
  dfi_en_offset_1 wrdata_cs_delay (
    .clock                 (clock),
    .reset                 (reset),
    .io_vld                (write_vld),
    .io_vld_ph0            (io_dfi_write_ph_0),
    .io_vld_ph1            (io_dfi_write_ph_1),
    .io_latency            ({27'h0, io_tphy_wrcslat}),
    .io_offset_out         (_wrdata_cs_delay_io_offset_out),
    .io_dfi_parameter_mode (io_dfi_parameter_mode)
  );
  dfi_en_offset_1 rddata_cs_delay (
    .clock                 (clock),
    .reset                 (reset),
    .io_vld                (read_vld),
    .io_vld_ph0            (io_dfi_read_ph_0),
    .io_vld_ph1            (io_dfi_read_ph_1),
    .io_latency            ({27'h0, io_tphy_rdcslat}),
    .io_offset_out         (_rddata_cs_delay_io_offset_out),
    .io_dfi_parameter_mode (io_dfi_parameter_mode)
  );
  dfi_en_offset rddata_en_delay (
    .clock                 (clock),
    .reset                 (reset),
    .io_vld                (read_vld),
    .io_vld_ph0            (io_dfi_read_ph_0),
    .io_vld_ph1            (io_dfi_read_ph_1),
    .io_latency            ({27'h0, io_trddata_en}),
    .io_offset_out         (io_dfi_rddata_in_dfi_rddata_en),
    .io_dfi_parameter_mode (io_dfi_parameter_mode)
  );
  assign io_dfi_ctrl_out_dfi_address_0 = io_dfi_ctrl_in_dfi_address_0;
  assign io_dfi_ctrl_out_dfi_address_1 = io_dfi_ctrl_in_dfi_address_1;
  assign io_dfi_ctrl_out_dfi_bank_0 = io_dfi_ctrl_in_dfi_bank_0;
  assign io_dfi_ctrl_out_dfi_bank_1 = io_dfi_ctrl_in_dfi_bank_1;
  assign io_dfi_ctrl_out_dfi_ras_n_0 = io_dfi_ctrl_in_dfi_ras_n_0;
  assign io_dfi_ctrl_out_dfi_ras_n_1 = io_dfi_ctrl_in_dfi_ras_n_1;
  assign io_dfi_ctrl_out_dfi_cas_n_0 = io_dfi_ctrl_in_dfi_cas_n_0;
  assign io_dfi_ctrl_out_dfi_cas_n_1 = io_dfi_ctrl_in_dfi_cas_n_1;
  assign io_dfi_ctrl_out_dfi_we_n_0 = io_dfi_ctrl_in_dfi_we_n_0;
  assign io_dfi_ctrl_out_dfi_we_n_1 = io_dfi_ctrl_in_dfi_we_n_1;
  assign io_dfi_ctrl_out_dfi_cs_n_0_0 = io_dfi_ctrl_in_dfi_cs_n_0_0;
  assign io_dfi_ctrl_out_dfi_cs_n_0_1 = io_dfi_ctrl_in_dfi_cs_n_0_1;
  assign io_dfi_ctrl_out_dfi_cs_n_1_0 = io_dfi_ctrl_in_dfi_cs_n_1_0;
  assign io_dfi_ctrl_out_dfi_cs_n_1_1 = io_dfi_ctrl_in_dfi_cs_n_1_1;
  assign io_dfi_ctrl_out_dfi_act_n_0 = io_dfi_ctrl_in_dfi_act_n_0;
  assign io_dfi_ctrl_out_dfi_act_n_1 = io_dfi_ctrl_in_dfi_act_n_1;
  assign io_dfi_ctrl_out_dfi_bg_0 = io_dfi_ctrl_in_dfi_bg_0;
  assign io_dfi_ctrl_out_dfi_bg_1 = io_dfi_ctrl_in_dfi_bg_1;
  assign io_dfi_ctrl_out_dfi_cid = io_dfi_ctrl_in_dfi_cid;
  assign io_dfi_ctrl_out_dfi_cke_0_0 = io_dfi_ctrl_in_dfi_cke_0_0;
  assign io_dfi_ctrl_out_dfi_cke_0_1 = io_dfi_ctrl_in_dfi_cke_0_1;
  assign io_dfi_ctrl_out_dfi_cke_1_0 = io_dfi_ctrl_in_dfi_cke_1_0;
  assign io_dfi_ctrl_out_dfi_cke_1_1 = io_dfi_ctrl_in_dfi_cke_1_1;
  assign io_dfi_ctrl_out_dfi_odt_0_0 = io_dfi_ctrl_in_dfi_odt_0_0;
  assign io_dfi_ctrl_out_dfi_odt_0_1 = io_dfi_ctrl_in_dfi_odt_0_1;
  assign io_dfi_ctrl_out_dfi_odt_1_0 = io_dfi_ctrl_in_dfi_odt_1_0;
  assign io_dfi_ctrl_out_dfi_odt_1_1 = io_dfi_ctrl_in_dfi_odt_1_1;
  assign io_dfi_ctrl_out_dfi_reset_n_0_0 = io_dfi_ctrl_in_dfi_reset_n_0_0;
  assign io_dfi_ctrl_out_dfi_reset_n_0_1 = io_dfi_ctrl_in_dfi_reset_n_0_1;
  assign io_dfi_ctrl_out_dfi_reset_n_1_0 = io_dfi_ctrl_in_dfi_reset_n_1_0;
  assign io_dfi_ctrl_out_dfi_reset_n_1_1 = io_dfi_ctrl_in_dfi_reset_n_1_1;
  assign io_dfi_wrdata_ch_out_dfi_wdata_cs_n = ~_wrdata_cs_delay_io_offset_out;
  assign io_dfi_rddata_in_dfi_rddata_cs_n = ~_rddata_cs_delay_io_offset_out;
  assign io_dfi_rddata_out = {RdData_buf_1, RdData_buf_0};
  assign io_dfi_rddata_ready = RdValid;
endmodule

module ddr4_init(
  input         clock,
                reset,
                io_apbDone,
  input  [15:0] io_mrs0,
                io_mrs1,
                io_mrs2,
                io_mrs3,
                io_mrs4,
                io_mrs5,
                io_mrs6,
  input  [7:0]  io_mrs_to_other,
  input  [3:0]  io_mrs_to_mrs,
  input  [20:0] io_dram_rstn,
  input         io_phy_dfi_init_complete,
  input  [23:0] io_pre_cke,
  input  [10:0] io_post_cke,
  input  [7:0]  io_sync_gear,
  input  [5:0]  io_cmd_gear,
  input  [7:0]  io_gear_setup,
                io_gear_hold,
  input         io_geardown_mode,
                io_block_tgeardown,
  input  [11:0] io_zqinit,
  output        io_zqlreq,
                io_dram_rst_n,
                io_init_cke,
                io_MrsReq,
                io_geardown_mode_init,
                io_geardown_sync_pulse_init,
                io_cal_on_init,
                io_MrsRank,
  output [1:0]  io_MrsBG,
                io_MrsBA,
  output [17:0] io_MrsAddr,
  output        io_end_init_ddr,
                io_init_in_progress,
  output [3:0]  io_init_curr_state,
                io_init_next_state
);

  reg  [3:0]       current_state;
  reg  [3:0]       last_state;
  reg              resetb_ff;
  reg              zqcl_ddr4;
  reg  [20:0]      timer_dram_rstn;
  reg  [23:0]      timer_cke;
  reg  [7:0]       timer_x1;
  reg  [11:0]      timer_zq;
  reg  [7:0]       timer_mode;
  reg              Mrs_Phase;
  wire             _io_init_cke_T_1 = current_state != 4'h1;
  wire             _mrs_bg_a_T = current_state == 4'hB;
  wire             _io_geardown_sync_pulse_init_T = last_state != current_state;
  wire             _mrs_bg_a_T_1 = current_state == 4'hA;
  wire             _mrs_bg_a_T_2 = current_state == 4'h9;
  wire             _mrs_bg_a_T_3 = current_state == 4'h5;
  wire             _io_cal_on_init_T = current_state == 4'h8;
  wire             _mrs_bg_a_T_7 = current_state == 4'h7;
  wire             _mrs_bg_a_T_8 = current_state == 4'h6;
  wire             _io_geardown_mode_init_T_1 = current_state == 4'h3;
  wire [2:0]       _mrs_bg_a_T_15 =
    _mrs_bg_a_T
      ? 3'h0
      : _mrs_bg_a_T_1
          ? 3'h1
          : _mrs_bg_a_T_2
              ? 3'h2
              : _mrs_bg_a_T_3 | _io_geardown_mode_init_T_1
                  ? 3'h3
                  : _io_cal_on_init_T
                      ? 3'h4
                      : _mrs_bg_a_T_7 ? 3'h5 : _mrs_bg_a_T_8 ? 3'h6 : 3'h0;
  wire [3:0]       _next_ddr_state_T_1 = {3'h0, ~(|timer_dram_rstn)};
  wire             _GEN = timer_x1 == 8'h0;
  wire [15:0][3:0] _GEN_0 =
    {{4'h0},
     {4'h0},
     {4'hD},
     {{3'h6, ~(|timer_zq)}},
     {(|timer_mode) ? 4'hB : Mrs_Phase ? 4'hC : 4'h5},
     {{3'h5, _GEN}},
     {(|timer_x1) ? 4'h9 : 4'hA},
     {{3'h4, _GEN}},
     {(|timer_x1) ? 4'h7 : 4'h8},
     {{3'h3, _GEN}},
     {(|timer_x1) ? 4'h5 : 4'h6},
     {{2'h1, ~((|timer_x1) & ~io_block_tgeardown), 1'h0}},
     {(|timer_x1) ? 4'h3 : 4'h4},
     {(|timer_cke) ? 4'h2 : io_geardown_mode ? 4'h3 : 4'h5},
     {(|timer_cke) ? 4'h1 : 4'h2},
     {4'h0}};
  wire [3:0]       _GEN_1 = _GEN_0[current_state];
  wire [3:0]       next_ddr_state = (|current_state) ? _GEN_1 : _next_ddr_state_T_1;
  wire [3:0]       next_state = io_apbDone ? next_ddr_state : 4'h0;
  wire             _set_timer_zq_T = next_state != current_state;
  wire [7:0]       _GEN_2 = {4'h0, io_mrs_to_mrs};
  always @(posedge clock or posedge reset) begin
    if (reset) begin
      current_state <= 4'h0;
      last_state <= 4'h0;
      resetb_ff <= 1'h0;
      zqcl_ddr4 <= 1'h0;
      timer_dram_rstn <= 21'hFF;
      timer_cke <= 24'h1;
      timer_x1 <= 8'h0;
      timer_zq <= 12'h0;
      timer_mode <= 8'hA;
      Mrs_Phase <= 1'h0;
    end
    else begin
      if (io_apbDone) begin
        if (|current_state)
          current_state <= _GEN_1;
        else
          current_state <= _next_ddr_state_T_1;
      end
      else
        current_state <= 4'h0;
      last_state <= current_state;
      resetb_ff <= 1'h1;
      zqcl_ddr4 <= current_state == 4'hC & last_state != 4'hC;
      if ((|timer_dram_rstn) & io_apbDone)
        timer_dram_rstn <= timer_dram_rstn - 21'h1;
      else if ((|timer_dram_rstn) & io_apbDone)
        timer_dram_rstn <= io_dram_rstn;
      if (~resetb_ff | ~(|current_state) | current_state == 4'h2
          | current_state == 4'h1) begin
        if (current_state != 4'h2 & next_state == 4'h2 & io_apbDone | _io_init_cke_T_1
            & next_state == 4'h1)
          timer_cke <=
            resetb_ff & io_apbDone & (|current_state) ? {13'h0, io_post_cke} : io_pre_cke;
        else if (|timer_cke)
          timer_cke <= timer_cke - 24'h1;
      end
      timer_x1 <=
        _set_timer_zq_T & next_ddr_state != 4'h2 & next_state != 4'hD & next_state != 4'h1
        & (|next_state) & next_state != 4'hC & next_state != 4'hB
          ? (next_state == 4'h3
               ? io_sync_gear + io_gear_setup + io_gear_hold
               : next_state == 4'h4
                   ? io_sync_gear + io_gear_setup
                   : io_geardown_mode & ~(io_mrs_to_mrs[0]) ? _GEN_2 + 8'h1 : _GEN_2)
          : (|timer_x1) ? timer_x1 - 8'h1 : timer_x1;
      if (_set_timer_zq_T & next_state == 4'hC)
        timer_zq <= io_zqinit;
      else if (|timer_zq)
        timer_zq <= timer_zq - 12'h1;
      if (current_state == 4'hB) begin
        if (|timer_mode)
          timer_mode <= timer_mode - 8'h1;
      end
      else
        timer_mode <= io_mrs_to_other;
      if (_mrs_bg_a_T & next_ddr_state == 4'h5)
        Mrs_Phase <= Mrs_Phase - 1'h1;
    end
  end // always @(posedge, posedge)
  `ifdef ENABLE_INITIAL_REG_
    `ifdef FIRRTL_BEFORE_INITIAL
      `FIRRTL_BEFORE_INITIAL
    `endif // FIRRTL_BEFORE_INITIAL
    initial begin
      if (reset) begin
        current_state = 4'h0;
        last_state = 4'h0;
        resetb_ff = 1'h0;
        zqcl_ddr4 = 1'h0;
        timer_dram_rstn = 21'hFF;
        timer_cke = 24'h1;
        timer_x1 = 8'h0;
        timer_zq = 12'h0;
        timer_mode = 8'hA;
        Mrs_Phase = 1'h0;
      end
    end // initial
    `ifdef FIRRTL_AFTER_INITIAL
      `FIRRTL_AFTER_INITIAL
    `endif // FIRRTL_AFTER_INITIAL
  `endif // ENABLE_INITIAL_REG_
  assign io_zqlreq = zqcl_ddr4;
  assign io_dram_rst_n = ~(|timer_dram_rstn) & io_apbDone & (|current_state);
  assign io_init_cke = (|current_state) & _io_init_cke_T_1;
  assign io_MrsReq =
    _io_geardown_sync_pulse_init_T
    & (_mrs_bg_a_T | _mrs_bg_a_T_1 | _mrs_bg_a_T_2 | _mrs_bg_a_T_3 | _io_cal_on_init_T
       | _mrs_bg_a_T_7 | _mrs_bg_a_T_8 | _io_geardown_mode_init_T_1);
  assign io_geardown_mode_init =
    _io_geardown_sync_pulse_init_T & _io_geardown_mode_init_T_1;
  assign io_geardown_sync_pulse_init =
    _io_geardown_sync_pulse_init_T & current_state == 4'h4;
  assign io_cal_on_init = _io_cal_on_init_T & (|(io_mrs4[8:6]));
  assign io_MrsRank = Mrs_Phase;
  assign io_MrsBG = {1'h0, _mrs_bg_a_T_15[2]};
  assign io_MrsBA = _mrs_bg_a_T_15[1:0];
  assign io_MrsAddr =
    _mrs_bg_a_T
      ? {2'h0, io_mrs0}
      : _mrs_bg_a_T_1
          ? {2'h0, io_mrs1}
          : _mrs_bg_a_T_2
              ? {2'h0, io_mrs2}
              : _mrs_bg_a_T_3
                  ? {2'h0, io_mrs3}
                  : _io_cal_on_init_T
                      ? {2'h0, io_mrs4}
                      : _mrs_bg_a_T_7
                          ? {2'h0, io_mrs5}
                          : _mrs_bg_a_T_8
                              ? {2'h0, io_mrs6}
                              : _io_geardown_mode_init_T_1
                                  ? {2'h0,
                                     io_mrs3[15:4],
                                     io_mrs3[3] | io_geardown_mode,
                                     io_mrs3[2:0]}
                                  : 18'hFFFF;
  assign io_end_init_ddr = current_state == 4'hD;
  assign io_init_in_progress = current_state != 4'hD;
  assign io_init_curr_state = current_state;
  assign io_init_next_state = next_state;
endmodule

module SCG_V3(
  input          clock,
                 reset,
  output [17:0]  io_dfi_dfictrl_dfi_address_0,
                 io_dfi_dfictrl_dfi_address_1,
  output [1:0]   io_dfi_dfictrl_dfi_bank_0,
                 io_dfi_dfictrl_dfi_bank_1,
