                 io_dfi_dfictrl_dfi_odt_0_0,
                 io_dfi_dfictrl_dfi_odt_0_1,
                 io_dfi_dfictrl_dfi_odt_1_0,
                 io_dfi_dfictrl_dfi_odt_1_1,
                 io_dfi_dfictrl_dfi_reset_n_0_0,
